export interface Env {
  AI: any;
  AUTH_SECRET?: string;
}

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

const DEFAULT_MODEL = '@cf/meta/llama-3.1-70b-instruct';

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // Handle CORS preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    // Health check
    if (url.pathname === '/' || url.pathname === '/health') {
      return new Response(
        JSON.stringify({ status: 'ok', worker: 'agentverse-ai-worker', defaultModel: DEFAULT_MODEL }),
        { headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
      );
    }

    // List models
    if (url.pathname === '/v1/models' || url.pathname === '/models') {
      const models = [
        { id: '@cf/meta/llama-3.1-70b-instruct', object: 'model', owned_by: 'cloudflare' },
        { id: '@cf/meta/llama-3.2-3b-instruct', object: 'model', owned_by: 'cloudflare' },
        { id: '@cf/mistral/mistral-7b-instruct-v0.1', object: 'model', owned_by: 'cloudflare' },
      ];
      return new Response(
        JSON.stringify({ object: 'list', data: models }),
        { headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
      );
    }

    // OpenAI compatible chat completions
    if (url.pathname === '/v1/chat/completions' || url.pathname === '/chat/completions') {
      if (request.method !== 'POST') {
        return new Response('Method not allowed', { status: 405, headers: CORS_HEADERS });
      }

      try {
        const body: any = await request.json();
        const model = body.model || DEFAULT_MODEL;
        const messages = body.messages || [];

        // Prepare messages for Cloudflare AI
        const cfMessages = messages.map((m: any) => ({
          role: m.role || 'user',
          content: typeof m.content === 'string' ? m.content : JSON.stringify(m.content),
        }));

        const aiPayload: any = {
          messages: cfMessages,
          stream: false,
          max_tokens: body.max_tokens || 3000,
          temperature: body.temperature ?? 0.7,
        };

        if (body.tools && Array.isArray(body.tools) && body.tools.length > 0) {
          aiPayload.tools = body.tools;
        }

        // Call Cloudflare Workers AI
        let aiResponse: any;
        try {
          aiResponse = await env.AI.run(model, aiPayload);
        } catch (runErr: any) {
          // If the model fails or tools aren't accepted with that model, retry without tools
          if (aiPayload.tools) {
            delete aiPayload.tools;
            aiResponse = await env.AI.run(model, aiPayload);
          } else {
            throw runErr;
          }
        }

        // Check if Cloudflare AI returned native tool_calls
        if (aiResponse?.tool_calls && Array.isArray(aiResponse.tool_calls) && aiResponse.tool_calls.length > 0) {
          const toolCalls = aiResponse.tool_calls.map((tc: any, i: number) => ({
            id: tc.id || `call_${Date.now()}_${i}`,
            type: 'function',
            function: {
              name: tc.name || tc.function?.name,
              arguments: typeof (tc.arguments || tc.function?.arguments) === 'string'
                ? (tc.arguments || tc.function?.arguments)
                : JSON.stringify(tc.arguments || tc.function?.arguments || {}),
            },
          }));

          const responsePayload = {
            id: `chatcmpl-${Date.now()}`,
            object: 'chat.completion',
            created: Math.floor(Date.now() / 1000),
            model: model,
            choices: [
              {
                index: 0,
                message: {
                  role: 'assistant',
                  content: null,
                  tool_calls: toolCalls,
                },
                finish_reason: 'tool_calls',
              },
            ],
            usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
          };

          return new Response(JSON.stringify(responsePayload), {
            headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
          });
        }

        let replyContent = aiResponse?.response || aiResponse?.text || (typeof aiResponse === 'string' ? aiResponse : JSON.stringify(aiResponse));

        // Check if the model emitted a tool call directly in text
        if (body.tools && Array.isArray(body.tools) && body.tools.length > 0) {
          const trimmed = replyContent.trim();
          try {
            // Check if output is a JSON tool call
            const parsed = JSON.parse(trimmed);
            const toolNames = body.tools.map((t: any) => t.function?.name || t.name);

            // Case 1: { name: 'runAgent', arguments: { ... } }
            if (parsed.name && toolNames.includes(parsed.name)) {
              const toolCalls = [{
                id: `call_${Date.now()}`,
                type: 'function',
                function: {
                  name: parsed.name,
                  arguments: typeof parsed.arguments === 'string' ? parsed.arguments : JSON.stringify(parsed.arguments || parsed.input || {}),
                },
              }];

              return new Response(JSON.stringify({
                id: `chatcmpl-${Date.now()}`,
                object: 'chat.completion',
                created: Math.floor(Date.now() / 1000),
                model: model,
                choices: [{ index: 0, message: { role: 'assistant', content: null, tool_calls: toolCalls }, finish_reason: 'tool_calls' }],
                usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
              }), { headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } });
            }

            // Case 2: { agent: '...', task: '...' } or { agentName: '...', task: '...' }
            if (parsed.agent || parsed.agentName) {
              const agentName = parsed.agent || parsed.agentName;
              const task = parsed.task || JSON.stringify(parsed.input || {});
              const toolCalls = [{
                id: `call_${Date.now()}`,
                type: 'function',
                function: {
                  name: 'runAgent',
                  arguments: JSON.stringify({ agentName, task }),
                },
              }];

              return new Response(JSON.stringify({
                id: `chatcmpl-${Date.now()}`,
                object: 'chat.completion',
                created: Math.floor(Date.now() / 1000),
                model: model,
                choices: [{ index: 0, message: { role: 'assistant', content: null, tool_calls: toolCalls }, finish_reason: 'tool_calls' }],
                usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
              }), { headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } });
            }
          } catch {
            // Not a tool call JSON, continue to normal handling
          }
        }

        // Schema / JSON response handling: ensure required schema property 'result' is satisfied if expected
        const isJsonExpected = body.response_format?.type === 'json_object' || 
          JSON.stringify(messages).includes('result') || 
          JSON.stringify(messages).includes('JSON');

        if (isJsonExpected) {
          try {
            const parsed = JSON.parse(replyContent.trim());
            if (parsed && typeof parsed === 'object' && !('result' in parsed)) {
              // Convert object into { result: formatted_string }
              replyContent = JSON.stringify({
                result: typeof parsed === 'string' ? parsed : (parsed.content || parsed.message || JSON.stringify(parsed, null, 2)),
              });
            }
          } catch {
            // Text was not JSON, wrap it into valid { result: "..." }
            replyContent = JSON.stringify({
              result: replyContent,
            });
          }
        }

        const responsePayload = {
          id: `chatcmpl-${Date.now()}`,
          object: 'chat.completion',
          created: Math.floor(Date.now() / 1000),
          model: model,
          choices: [
            {
              index: 0,
              message: {
                role: 'assistant',
                content: replyContent,
              },
              finish_reason: 'stop',
            },
          ],
          usage: {
            prompt_tokens: 0,
            completion_tokens: 0,
            total_tokens: 0,
          },
        };

        return new Response(JSON.stringify(responsePayload), {
          headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
        });
      } catch (err: any) {
        console.error('Error generating AI response:', err);
        return new Response(
          JSON.stringify({
            error: {
              message: err.message || 'Error communicating with Cloudflare AI',
              type: 'cf_ai_error',
            },
          }),
          { status: 500, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
        );
      }
    }

    return new Response('Not Found', { status: 404, headers: CORS_HEADERS });
  },
};
